<template><section class="diary-dashboard"><diario-soporte vista="equipo" /><header class="diary-personal-head"><div><h2>Dashboard general de actividades</h2><p>Superadmin · Información de todas las cuentas, sin recordatorios personales.</p></div><a :href="exportUrl" :class="['diary-export',{disabled:dirty || loading || !data}]" @click="preventExport">Descargar reporte CSV</a></header><div class="diary-filters"><label>Desde<input type="date" v-model="filters.desde" required></label><label>Hasta<input type="date" v-model="filters.hasta" required></label><label>Responsable<select v-model="filters.responsable"><option value="">Todos</option><optgroup label="Usuarios"><option v-for="u in context.usuarios" :key="u.Usuario" :value="'u:'+u.Usuario">{{u.NombreUsuario || u.Usuario}}</option></optgroup><optgroup label="Empleados"><option v-for="e in context.empleados" :key="e.IdEmpleado" :value="'e:'+e.IdEmpleado">{{e.Empleado}}</option></optgroup></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><label>Calificación<select v-model="filters.calidad"><option value="">Todas</option><option v-for="n in [5,4,3,2,1]" :key="n" :value="String(n)">{{n}} / 5</option><option value="sin">Concluidas sin calificar</option></select></label><label>Área de trabajo<select v-model="filters.tipo"><option value="">Todas</option><option value="programacion">Programación</option><option value="soporte">Soporte</option><option value="mantenimiento">Mantenimiento</option><option value="reunion">Reuniones</option><option value="general">General</option></select></label><label>Proyecto / cliente / ticket<input v-model="filters.buscar" maxlength="180" placeholder="Empresa, DEV-45, SUP-123..."></label><button type="button" :disabled="loading" @click="consult">{{loading?'Consultando…':'Consultar reporte'}}</button></div><p v-if="error" class="diary-error" role="alert">{{error}}</p><p v-if="dirty" class="diary-error">Filtros modificados. Consulta para actualizar el reporte.</p><template v-if="data"><p class="diary-hint">Periodo consultado: {{applied.desde}} al {{applied.hasta}} · Lima. Incluye actividades cuyo horario previsto se cruza con este rango. Totales calculados sobre todo el resultado, no solo la página visible.</p><div class="diary-stats"><article><span>Actividades</span><strong>{{data.resumen.total}}</strong></article><article><span>Concluidas</span><strong>{{data.resumen.concluidas}}</strong></article><article><span>Calificación promedio</span><strong>{{data.resumen.calidad===null?'—':data.resumen.calidad}} / 5</strong></article><article><span>Logros validados</span><strong>{{data.resumen.validadas}}</strong></article><article><span>Vencidas pendientes</span><strong>{{data.resumen.vencidas}}</strong></article><article><span>Logro ponderado</span><strong>{{data.resumen.logro}}%</strong></article></div><div class="diary-stats"><article><span>Programación concluida / total</span><strong>{{data.resumen.programacionConcluida || 0}} / {{data.resumen.programacion || 0}}</strong></article><article><span>Soporte concluido / total</span><strong>{{data.resumen.soporteResuelto || 0}} / {{data.resumen.soporte || 0}}</strong></article><article><span>Tiempo estimado asignado</span><strong>{{duration((data.resumen.estimadoMin || 0)*60)}}</strong></article></div><div class="diary-dashboard-charts"><section class="diary-team"><h3>Estado de las actividades</h3><div class="diary-grade-bars"><div v-for="(label,key) in labels" :key="key"><span class="diary-wide-label">{{label}}</span><div><i :style="{width:(data.resumen.total?(data.estados[key]||0)*100/data.resumen.total:0)+'%'}"></i></div><strong>{{data.estados[key] || 0}}</strong></div></div></section><section class="diary-team"><h3>Distribución de calificaciones</h3><div class="diary-grade-bars"><div v-for="n in [5,4,3,2,1]" :key="n"><span>{{n}} / 5</span><div><i :style="{width:(data.resumen.validadas?(data.calificaciones[n]||0)*100/data.resumen.validadas:0)+'%'}"></i></div><strong>{{data.calificaciones[n] || 0}}</strong></div></div><p class="diary-hint">{{data.resumen.concluidas-data.resumen.validadas}} concluidas pendientes de calificación.</p></section></div><section class="diary-team"><h3>Resultados por empleado y cargo</h3><div class="diary-table-wrap"><table><thead><tr><th>Empleado / Cargo</th><th>Actividades</th><th>Concluidas</th><th>Validadas</th><th>Calificación</th><th>Cumplimiento</th><th>Puntualidad</th><th>Puntos logrados</th><th>Logro ponderado</th><th>Vencidas</th><th>Tiempo estimado</th><th>Programación concluida</th><th>Soporte concluido</th><th>Tiempo trabajado</th></tr></thead><tbody><tr v-for="g in data.equipo" :key="g.key"><td>{{g.nombre}}<small>{{g.cargo || 'Sin cargo vinculado'}}</small></td><td>{{g.total}}</td><td>{{g.concluidas}}</td><td>{{g.validadas}}</td><td>{{g.calidad===null?'—':g.calidad+' / 5'}}</td><td>{{g.cumplimiento}}%</td><td>{{g.puntualidad}}%</td><td>{{g.logrados}} / {{g.posibles}}</td><td>{{g.logro}}%</td><td>{{g.vencidas}}</td><td>{{duration((g.estimadoMin || 0)*60)}}</td><td>{{g.programacionConcluida || 0}} / {{g.programacion || 0}}</td><td>{{g.soporteResuelto || 0}} / {{g.soporte || 0}}</td><td>{{duration(g.segundos)}}</td></tr><tr v-if="!data.equipo.length"><td colspan="14">Sin actividades para los filtros consultados.</td></tr></tbody></table></div><p class="diary-hint">Cumplimiento = concluidas / tareas no canceladas. Puntualidad = concluidas a tiempo / concluidas. Logro ponderado combina peso, meta lograda y calidad validada. Las remuneraciones se deciden manualmente.</p></section><section class="diary-team"><h3>Lista de actividades por fechas</h3><p>{{data.resumen.total}} actividades · Página {{data.pagina}} de {{data.paginas}} · Hasta 100 por página</p><div class="diary-table-wrap"><table><thead><tr><th>ID</th><th>Responsable</th><th>Área / Proyecto / Ticket</th><th>Actividad</th><th>Inicio · Lima</th><th>Fin · Lima</th><th>Estado</th><th>Meta / Resultado</th><th>Calificación</th><th>Conclusión</th><th>Evidencias y detalle</th></tr></thead><tbody><tr v-for="t in data.actividades" :key="t.Id"><td>{{t.Id}}</td><td>{{t.ResponsableNombre}}</td><td class="diary-feedback">{{typeName(t.TipoTrabajo)}}<br>{{t.Proyecto || 'Sin proyecto'}}<small>{{t.Ticket}}</small></td><td class="diary-feedback">{{t.Titulo}}</td><td>{{t.Inicio}}</td><td>{{t.Fin}}</td><td>{{labels[t.Estado]}}</td><td>{{Number(t.Objetivo)>0?t.Realizado+' / '+t.Objetivo+' '+t.Unidad:'Cualitativa'}}</td><td>{{t.Calidad===null?'Sin calificar':t.Calidad+' / 5'}}</td><td>{{t.FinReal || '—'}}</td><td>{{t.CantidadAdjuntos || 0}} imágenes<br><button type="button" @click="openDetail(t)">Ver reporte detallado</button></td></tr><tr v-if="!data.actividades.length"><td colspan="11">No hay actividades en esta selección.</td></tr></tbody></table></div><div class="diary-pagination"><button type="button" :disabled="loading || dirty || data.pagina<=1" @click="load(data.pagina-1)">Anterior</button><button type="button" :disabled="loading || dirty || data.pagina>=data.paginas" @click="load(data.pagina+1)">Siguiente</button></div></section></template><b-modal modal-class="diary-modal-premium" v-model="detailOpen" title="Reporte detallado de actividad" hide-footer size="lg"><div v-if="selected" class="diary-form"><h3>{{selected.Titulo}}</h3><p>{{selected.ResponsableNombre}} · {{selected.Cargo || 'Sin cargo'}} · {{typeName(selected.TipoTrabajo)}}</p><div class="diary-report-facts"><span><small>Cliente / proyecto</small>{{selected.Proyecto || '—'}}</span><span><small>Ticket / commit</small>{{selected.Ticket || '—'}}</span><span><small>Estado</small>{{labels[selected.Estado]}}</span><span><small>Estimado</small>{{duration((selected.EstimadoMin || 0)*60)}}</span><span><small>Trabajado</small>{{duration(actualSeconds(selected))}}</span><span><small>Calificación</small>{{selected.Calidad===null?'Sin evaluar':selected.Calidad+' / 5'}}</span><span><small>Inicio previsto</small>{{selected.Inicio}}</span><span><small>Fin previsto</small>{{selected.Fin}}</span><span><small>Inicio real</small>{{selected.InicioReal || '—'}}</span><span><small>Conclusión real</small>{{selected.FinReal || '—'}}</span></div><section><strong>Indicaciones</strong><p class="diary-instructions">{{selected.Indicaciones || 'Sin indicaciones'}}</p></section><section><strong>Resultado alcanzado</strong><p class="diary-instructions">{{selected.Resultado || 'Aún no registrado'}}</p><p v-if="Number(selected.Objetivo)>0">Meta: {{selected.Realizado}} / {{selected.Objetivo}} {{selected.Unidad}}</p><p>Evidencia o referencia: {{selected.Evidencia || '—'}}</p></section><section><strong>Evaluación y reconocimiento</strong><p class="diary-instructions">{{selected.Reconocimiento || 'Pendiente de evaluación'}}</p><small>{{selected.Evaluador}} {{selected.FechaEvaluacion}}</small></section><diario-adjuntos v-if="detailOpen" :task-id="selected.Id" :context="context" readonly /><h4>Historial de avances</h4><p v-if="detailError" class="diary-error">{{detailError}}</p><ol class="diary-events"><li v-for="e in events" :key="e.Id"><strong>{{e.Usuario}} · {{e.Accion}}</strong><small>{{e.Fecha}}</small><p>{{e.Texto}}</p></li></ol></div></b-modal></section></template>
<script>
import DiarioSoporte from '@/components/DiarioSoporte.vue';
import DiarioAdjuntos from '@/components/DiarioAdjuntos.vue';
import config from '@/store/config';
import {limaInput} from '@/utils/diario';
export default {components:{DiarioAdjuntos,DiarioSoporte},props:{context:{type:Object,required:true}},data(){const today=limaInput().slice(0,10);return {detailOpen:false,selected:null,events:[],detailError:'',filters:{desde:today.slice(0,7)+'-01',hasta:today,responsable:'',estado:'',calidad:'',tipo:'',buscar:''},applied:null,data:null,error:'',loading:false,labels:{pendiente:'Pendientes',en_curso:'En curso',pausada:'Pausadas',concluida:'Concluidas',cancelada:'Canceladas'}}},computed:{dirty(){return this.applied&&JSON.stringify(this.filters)!==JSON.stringify(this.applied)},exportUrl(){return config.API+'diario/reporte.csv?'+this.query(this.applied||this.filters)}},mounted(){this.consult()},methods:{typeName(t){return {general:'General',programacion:'Programación',soporte:'Soporte',mantenimiento:'Mantenimiento',reunion:'Reunión'}[t] || 'General'},actualSeconds(t){return Number(t.Segundos || 0)+(t.EnCursoDesde?Math.max(0,(Date.now()-Date.parse(t.EnCursoDesde.replace(' ','T')+'-05:00'))/1000):0)},async openDetail(t){this.selected=t;this.events=[];this.detailError='';this.detailOpen=true;try{const r=await this.axios.get(config.API+'diario/tareas/'+t.Id+'/eventos',{timeout:15000});this.events=r.data}catch(e){this.detailError='No se pudo cargar el historial.'}},query(p){return Object.keys(p).map(k=>encodeURIComponent(k)+'='+encodeURIComponent(p[k])).join('&')},duration(s){const m=Math.floor(s/60);return Math.floor(m/60)+' h '+String(m%60).padStart(2,'0')+' min'},preventExport(e){if(this.dirty||this.loading||!this.data)e.preventDefault()},consult(){this.load(1,Object.assign({},this.filters))},async load(page,filters=this.applied){if(this.loading)return;this.loading=true;this.error='';try{const r=await this.axios.get(config.API+'diario/dashboard?'+this.query(filters)+'&pagina='+page,{timeout:30000});this.data=r.data;this.applied=filters}catch(e){this.error=e.response&&e.response.data.error||'No se pudo cargar el reporte.'}finally{this.loading=false}}}};
</script>
<style>.diary-dashboard h3{font-size:18px}.diary-dashboard .diary-stats{grid-template-columns:repeat(3,minmax(0,1fr))}.diary-dashboard-charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.diary-grade-bars>div>.diary-wide-label{width:90px}.diary-export{background:#087f75;color:white;padding:11px 16px;border-radius:10px;font-size:13px;font-weight:bold;white-space:nowrap}.diary-export.disabled{opacity:.5;cursor:default}.diary-pagination{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}@media(max-width:800px){.diary-dashboard-charts{grid-template-columns:minmax(0,1fr)}.diary-dashboard .diary-stats{grid-template-columns:repeat(2,minmax(0,1fr))}}.diary-report-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:16px;background:#f3f7fa;border-radius:12px;font-size:12px}.diary-report-facts small{display:block;color:#7b91a2;margin-bottom:4px}@media(max-width:600px){.diary-report-facts{grid-template-columns:minmax(0,1fr)}}
</style>
